<?php
if(!defined('ABSPATH')){exit;}
final class NVConsult_Core_Automation_Rules{
 public static function init():void{add_action('save_post_nv_application',[self::class,'application_saved'],90,3);add_action('nvconsult_daily_followups',[self::class,'daily'],20);}
 public static function application_saved(int$id,WP_Post$p,bool$update):void{if(wp_is_post_revision($id)||$p->post_status!=='private')return;$status=(string)get_post_meta($id,'_nvconsult_status',true);$assigned=absint(get_post_meta($id,'_nvconsult_assigned_user_id',true));if(!$assigned&&in_array($status,['new','reviewing'],true))self::log($id,'automation',__('Application is unassigned and requires ownership.','nvconsult-core'));if($status==='documents'){foreach(NVConsult_Core_Document_Requests::items($id)as$r)if($r['status']==='required')return;self::log($id,'automation',__('Document stage has no outstanding document requests. Staff review recommended.','nvconsult-core'));}}
 public static function daily():void{$today=current_time('Y-m-d');$contacts=get_posts(['post_type'=>'nv_contact','post_status'=>'publish','numberposts'=>-1]);foreach($contacts as$c){$d=(string)get_post_meta($c->ID,'_nvconsult_next_action',true);if($d&&$d<=$today&&!get_post_meta($c->ID,'_nvconsult_crm_alert_'.$today,true)){wp_mail(get_option('admin_email'),__('NVConsult CRM follow-up due','nvconsult-core'),sprintf(__('CRM contact "%1$s" has a follow-up due on %2$s.','nvconsult-core'),$c->post_title,$d));update_post_meta($c->ID,'_nvconsult_crm_alert_'.$today,1);}}$partners=get_posts(['post_type'=>'nv_partner','post_status'=>'publish','numberposts'=>-1]);foreach($partners as$p){$d=(string)get_post_meta($p->ID,'_nvconsult_next_followup',true);if($d&&$d<=$today&&!get_post_meta($p->ID,'_nvconsult_partner_alert_'.$today,true)){wp_mail(get_option('admin_email'),__('NVConsult partner follow-up due','nvconsult-core'),sprintf(__('Partner "%1$s" has a follow-up due on %2$s.','nvconsult-core'),$p->post_title,$d));update_post_meta($p->ID,'_nvconsult_partner_alert_'.$today,1);}}}
 private static function log(int$id,string$type,string$text):void{$key='_nvconsult_auto_'.md5($type.$text.current_time('Y-m-d'));if(get_post_meta($id,$key,true))return;add_post_meta($id,'_nvconsult_history',['type'=>$type,'message'=>$text,'time'=>current_time('mysql'),'user_id'=>0]);update_post_meta($id,$key,1);}
}
